"use strict";(self.webpackChunkhalt_website=self.webpackChunkhalt_website||[]).push([["26835"],{66980(e){e.exports=JSON.parse('{"tag":{"label":"Rescue","permalink":"/docs/tags/rescue","allTagsPath":"/docs/tags","count":21,"items":[{"id":"general-care/getting-a-pet/are-you-ready-for-a-pet","title":"Are You Ready for a Pet?","description":"Before bringing any animal home, ask yourself the hard questions. This guide covers the most common reasons pets are surrendered \u2014 and what to think through before it ever comes to that.","permalink":"/docs/general-care/getting-a-pet/are-you-ready-for-a-pet"},{"id":"rescue-resources/so-you-want-to-run-a-rescue/establish-your-network","title":"Establish Your Network: The Power of Community","description":"A guide for animal rescues on the importance of building a strong network of volunteers, foster homes, veterinary partners, and community supporters.","permalink":"/docs/rescue-resources/so-you-want-to-run-a-rescue/establish-your-network"},{"id":"rescue-resources/so-you-want-to-run-a-rescue/getting-started","title":"Getting Started: The Foundation of Your Rescue","description":"The essential first steps to starting an animal rescue, including defining your mission, building a board, and navigating the legal process of becoming a 501(c)(3) nonprofit.","permalink":"/docs/rescue-resources/so-you-want-to-run-a-rescue/getting-started"},{"id":"rescue-resources/so-you-want-to-run-a-rescue/getting-supplies","title":"Getting Supplies: Equipping Your Rescue for Success","description":"A practical guide for new animal rescues on how to acquire the essential supplies needed to care for animals, from food and housing to medical equipment.","permalink":"/docs/rescue-resources/so-you-want-to-run-a-rescue/getting-supplies"},{"id":"general-care/getting-a-pet/foundpet","title":"Help, I Found a Pet!","description":"What to do if you find a lost domestic small pet or an injured/orphaned wild animal. Covers identification, safe containment, temperature, and how to find a wildlife rehabilitator.","permalink":"/docs/general-care/getting-a-pet/foundpet"},{"id":"general-care/getting-a-pet/rehome","title":"How to Rehome a Pet","description":"We all hope to keep our pets forever, but sometimes life happens and unfortunately, we have to find a new home for our pets. Here is some advice for safely rehoming your pets.","permalink":"/docs/general-care/getting-a-pet/rehome"},{"id":"rescue-resources/so-you-want-to-run-a-rescue/level-up-your-skills","title":"Level Up Your Skills: From Passion to Profession","description":"A guide for established animal rescues on how to level up their skills in advanced medical care, fundraising, and nonprofit management for long-term sustainability.","permalink":"/docs/rescue-resources/so-you-want-to-run-a-rescue/level-up-your-skills"},{"id":"rescue-resources/Report/report-ct","title":"Report Pet Store Neglect in Connecticut","description":"1\\\\. Who actually investigates in Connecticut?","permalink":"/docs/rescue-resources/Report/report-ct"},{"id":"rescue-resources/Report/report-ma","title":"Report Pet Store Neglect in Massachusetts","description":"1\\\\. Who investigates animal cruelty in Massachusetts?","permalink":"/docs/rescue-resources/Report/report-ma"},{"id":"rescue-resources/Report/report-nh","title":"Report Pet Store Neglect in New Hampshire","description":"1\\\\. Who to contact & oversight","permalink":"/docs/rescue-resources/Report/report-nh"},{"id":"rescue-resources/Report/report-nj","title":"Report Pet Store Neglect in New Jersey","description":"New Jersey Public Guide","permalink":"/docs/rescue-resources/Report/report-nj"},{"id":"rescue-resources/Report/report-ny","title":"Report Pet Store Neglect in New York","description":"1. Oversight & Agencies to Contact","permalink":"/docs/rescue-resources/Report/report-ny"},{"id":"rescue-resources/Report/report-pa","title":"Report Pet Store Neglect in Pennsylvania","description":"1\\\\. Oversight & jurisdiction for small animals in Pennsylvania","permalink":"/docs/rescue-resources/Report/report-pa"},{"id":"rescue-resources/so-you-want-to-run-a-rescue/vets","title":"Rescue and Veterinary Care: What You Owe the Animals","description":"When you run a rescue, you take on a lot \u2014 shelter, food, enrichment, cleaning, and of course\u2026 medical care. And let\u2019s be real: a lot of that falls to us. We clean wounds, administer medications, track symptoms, manage chronic conditions, and make hard decisions.","permalink":"/docs/rescue-resources/so-you-want-to-run-a-rescue/vets"},{"id":"rescue-resources/so-you-want-to-run-a-rescue/the-true-cost","title":"So You Want to Run a Rescue? Part 1: The True Cost of Saving Lives","description":"Part 1 of a series on running an animal rescue, focusing on the significant and often underestimated financial costs involved, from veterinary bills to daily supplies.","permalink":"/docs/rescue-resources/so-you-want-to-run-a-rescue/the-true-cost"},{"id":"rescue-resources/so-you-want-to-run-a-rescue/the-emotional-gauntlet","title":"So You Want to Run a Rescue? Part 2: The Emotional Gauntlet","description":"Part 2 of a series on running an animal rescue, exploring the intense emotional challenges, including compassion fatigue, burnout, and the difficulty of making life-and-death decisions.","permalink":"/docs/rescue-resources/so-you-want-to-run-a-rescue/the-emotional-gauntlet"},{"id":"rescue-resources/so-you-want-to-run-a-rescue/the-physical-toll","title":"So You Want to Run a Rescue? Part 3: The Physical Toll & Unseen Labor","description":"Part 3 of a series on running an animal rescue, detailing the intense, often invisible physical labor and the 24/7 time commitment that rescue work demands.","permalink":"/docs/rescue-resources/so-you-want-to-run-a-rescue/the-physical-toll"},{"id":"rescue-resources/so-you-want-to-run-a-rescue/building-a-sustainable-future","title":"So You Want to Run a Rescue? Part 4: Building a Sustainable Future","description":"Part 4 of a series on running an animal rescue, focusing on strategies for building a sustainable organization that can survive long-term, including effective fundraising, volunteer management, and preventing burnout.","permalink":"/docs/rescue-resources/so-you-want-to-run-a-rescue/building-a-sustainable-future"},{"id":"general-care/sensitive-topics/animal-hoarding","title":"The Shadow of Compassion: Understanding and Addressing Animal Hoarding","description":"Animal hoarding is a complex and tragic issue that sits at the intersection of animal welfare, public health, and mental illness. It is not born from a place of malice, but often from a deeply misguided sense of love and a compulsive need to \u201Csave\u201D animals. This article aims to shed light on this sensitive topic with the delicacy it deserves, providing guidance for individuals who may be struggling, as well as for rescues navigating these difficult situations.","permalink":"/docs/general-care/sensitive-topics/animal-hoarding"},{"id":"rescue-resources/so-you-want-to-run-a-rescue/transparency","title":"Transparency Is Not Optional \u2014 It\u2019s Foundational","description":"In rescue, transparency isn\u2019t a nice-to-have \u2014 it\u2019s essential.","permalink":"/docs/rescue-resources/so-you-want-to-run-a-rescue/transparency"},{"id":"rescue-resources/so-you-want-to-run-a-rescue/budget","title":"Why Budgeting is Important","description":"When people imagine running an animal rescue, they picture cuddles, cute faces, and happy adoptions. What they don\u2019t always see is the spreadsheet behind the scenes.","permalink":"/docs/rescue-resources/so-you-want-to-run-a-rescue/budget"}],"unlisted":false}}')}}]);